def next_smallest_palindrome(num: int) -> int:
    s = str(num + 1)
    length = len(s)

    # A helper to check if all digits are 9
    if all(c == '9' for c in s):
        # Next palindrome after 999..9 is 100..001
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[:-1][::-1])
        else:
            return int(left + left[::-1])

    odd = (length % 2 != 0)
    mid = (length // 2)
    if odd:
        left = s[:mid+1]
    else:
        left = s[:mid]

    pal = make_palindrome(left, odd)
    if pal >= int(s):
        return pal

    # Increment the left part and form palindrome again
    if odd:
        incremented = str(int(left) + 1)
        # If length changes after increment, e.g. 999 + 1 = 1000
        if len(incremented) > len(left):
            # This means palindrome length increases by 1
            return int('1' + ('0' * (length - 1)) + '1')
        return make_palindrome(incremented, odd)
    else:
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            return int('1' + ('0' * (length - 1)) + '1')
        return make_palindrome(incremented, odd)

def find_solution(a, b, n):
    # Find first non-negative integer solution (x,y) to ax + by = n with smallest x starting from 0
    # Returns (x,y) or 'No solution' if none exists

    # Handle trivial cases
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else 'No solution'
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return 'No solution'
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return 'No solution'

    # To find integer solutions to ax + by = n, first check if gcd divides n
    from math import gcd
    g = gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # Reduce the equation by gcd
    a1, b1, n1 = a // g, b // g, n // g

    # We want to find x >= 0 and y >= 0 such that a1*x + b1*y = n1

    # Try x from 0 up to n1 // a1 (max possible x)
    max_x = n1 // a1 if a1 != 0 else 0
    for x in range(max_x + 1):
        rem = n1 - a1 * x
        if rem < 0:
            break
        if rem % b1 == 0:
            y = rem // b1
            if y >= 0:
                return (x, y)

    return 'No solution'

