def find_solution(a, b, n):
    # We want non-negative integers x,y such that a*x + b*y = n.
    # Return (x,y) or None if no solution.
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    from math import gcd

    g = gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find one solution to a*x + b*y = g
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, x1, y1 = extended_gcd(y, x % y)
        return (g, y1, x1 - (x // y) * y1)

    g, x0, y0 = extended_gcd(a, b)
    # scale to n
    x0 *= n // g
    y0 *= n // g

    # a and b scaled down
    a_div = a // g
    b_div = b // g

    # General solution: x = x0 + k * (b/g), y = y0 - k * (a/g)
    # We want to find k so that x >= 0 and y >= 0

    # From x >= 0:
    # x0 + k * b_div >= 0 => k >= -x0 / b_div

    # From y >= 0:
    # y0 - k * a_div >= 0 => k <= y0 / a_div

    # So k must satisfy:
    # ceil(-x0 / b_div) <= k <= floor(y0 / a_div)

    # Note b_div and a_div are positive (since g divides both a,b)
    from math import ceil, floor

    k_min = ceil(-x0 / b_div)
    k_max = floor(y0 / a_div)

    if k_min > k_max:
        return None

    # Any k in [k_min, k_max] works; choose k = k_min
    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        return None

    return (x, y)

