def dict_depth(d):
    if not isinstance(d, dict):
        return 0

    def helper(obj, current_depth):
        if isinstance(obj, dict):
            max_depth = current_depth + 1
            for v in obj.values():
                max_depth = max(max_depth, helper(v, current_depth + 1))
            return max_depth
        elif isinstance(obj, (list, tuple)):
            max_depth = current_depth
            for item in obj:
                max_depth = max(max_depth, helper(item, current_depth))
            return max_depth
        else:
            return current_depth

    return helper(d, 0)

