def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd and one solution (x0, y0) to ax + by = gcd(a,b)
    def extended_gcd(aa, bb):
        if bb == 0:
            return aa, 1, 0
        gcd, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - (aa // bb) * y1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return 'No solution'

    # Scale the initial solution to n
    x0 *= n // gcd
    y0 *= n // gcd

    # a and b divided by gcd
    a_div = a // gcd
    b_div = b // gcd

    # We want smallest non-negative x:
    # General solution: x = x0 + k * (b/gcd), y = y0 - k * (a/gcd)
    # Find k such that x >= 0 and minimal
    # Solve x0 + k * b_div >= 0  =>  k >= -x0/b_div
    # k must be integer, so k = ceil(-x0 / b_div) if b_div > 0, else floor(-x0 / b_div)
    # Then check the solution with that k

    from math import ceil, floor

    if b_div > 0:
        k = ceil(-x0 / b_div)
    elif b_div < 0:
        k = floor(-x0 / b_div)
    else:
        # b_div == 0 means b==0 => equation is a*x = n
        # in that case, y can be anything, just check x0 >= 0
        if x0 < 0:
            return 'No solution'
        else:
            return (x0, y0)

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0:
        return 'No solution'
    else:
        return (x, y)

