def permute_string(s: str) -> List[str]:
    def backtrack(path, counter, length, res):
        if len(path) == length:
            res.append("".join(path))
            return
        for char in counter:
            if counter[char] > 0:
                path.append(char)
                counter[char] -= 1
                backtrack(path, counter, length, res)
                counter[char] += 1
                path.pop()

    counter = {}
    for char in s:
        counter[char] = counter.get(char, 0) + 1
    result = []
    backtrack([], counter, len(s), result)
    return result

