def find_Max(arr, low, high):
    # Handle empty array case
    if not arr or low > high:
        raise ValueError("Array is empty or invalid indices")

    # If the array is not rotated at all
    if high < low:
        return arr[high]

    # If there is only one element left
    if low == high:
        return arr[low]

    mid = (low + high) // 2

    # Check if mid element is greater than its next element
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # Check if mid element is smaller than its previous element
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide whether to go to the left half or right half
    if arr[low] >= arr[mid]:
        return find_Max(arr, low, mid - 1)
    return find_Max(arr, mid + 1, high)

