def next_smallest_palindrome(num: int) -> int:
    def is_all_nines(n: int) -> bool:
        return all(ch == '9' for ch in str(n))

    s = str(num)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if is_all_nines(num):
        return int('1' + ('0' * (length - 1)) + '1')

    # Increment num by 1 since we want strictly greater palindrome
    num += 1
    s = str(num)
    length = len(s)

    # Split into left, middle, right
    if length % 2 == 0:
        left = s[:length//2]
        middle = ''
        right = s[length//2:]
    else:
        left = s[:length//2]
        middle = s[length//2]
        right = s[length//2+1:]

    # Form a palindrome by mirroring left and middle
    if middle:
        palindrome = left + middle + left[::-1]
    else:
        palindrome = left + left[::-1]

    if int(palindrome) >= num:
        return int(palindrome)

    # Need to increment the middle part and mirror again
    if middle:
        # Increment the middle + left part as a number
        left_middle_num = int(left + middle)
        left_middle_num += 1
        left_middle_str = str(left_middle_num)

        # If length changed, means we have a carry over (e.g. 999 + 1 = 1000)
        if len(left_middle_str) > len(left + middle):
            # This happens when palindrome length grows by 1
            # For example, 999 -> 1001 handled above, but in this step,
            # just form palindrome again accordingly
            return int(left_middle_str + left_middle_str[:-1][::-1])

        left = left_middle_str[:-1]
        middle = left_middle_str[-1]
        palindrome = left + middle + left[::-1]
        return int(palindrome)
    else:
        # Even length case
        left_num = int(left)
        left_num += 1
        left_str = str(left_num)

        # If length changed due to carry (e.g. 99 -> 100)
        if len(left_str) > len(left):
            # Length increases by one digit, palindrome length increases by 2
            return int(left_str + left_str[:-1][::-1])

        palindrome = left_str + left_str[::-1]
        return int(palindrome)

