def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    # Check all right shifts
    # Right shift k times means arr[-k:] + arr[:-k]
    for k in range(n):
        shifted = arr[-k:] + arr[:-k]
        if is_non_decreasing(shifted):
            return True
    return False

